function setForgeBuild(n,mods){const weapon=Number($('forgeGun'+n).value),limit=getModSlots(weapon);for(const [j,selector] of forgeMods(n).entries()){const mod=mods?.[j];selector.value=j<limit&&MODS[mod]?.slot===j&&MODS[mod].level<=masteryLevel(weapon)?mod:'';}forgeEditors[n]=-1;syncForgeWorkbench();renderForgePreview();}
