function useAmmoBox(){if(!game||paused||mapOpen)return;const p=game.player;if(!p.ammoBoxes){announce('MERMİ KUTUN YOK',.9);return;}saveSlot();const targets=p.slots.filter(q=>q&&q.reserve<AMMO_MAX[q.weapon]);if(!targets.length){announce('TÜM YEDEK MERMİLER DOLU',.9);return;}p.ammoBoxes--;for(const q of targets)q.reserve=Math.min(AMMO_MAX[q.weapon],q.reserve+Math.max(MAG_SIZE[q.weapon]*4,Math.ceil(AMMO_MAX[q.weapon]*.35)));if(p.activeSlot>=0)p.reserve=p.slots[p.activeSlot]?.reserve??0;burst(currentRoom(),p.x+p.w/2,p.y+p.h/2,'#ffd36d',17,130);floating(p.x,p.y-24,'+ MERMİ','#ffd36d');sound(790,.14,'triangle');updateHud();}
function throwGrenade(){if(!game||paused||mapOpen||game.dead||game.won)return;const p=game.player;if(!p.grenades){announce('BOMBAN KALMADI',.8);return;}p.grenades--;const dx=mouse.x-(p.x+p.w/2),dy=mouse.y-(p.y+p.h/2),angle=Math.atan2(dy,dx);game.grenades.push({x:p.x+p.w/2,y:p.y+p.h*.4,vx:Math.cos(angle)*450,vy:Math.sin(angle)*360-210,time:1.2});sound(390,.12,'triangle');updateHud();}
function explodeGrenade(g){const room=currentRoom();burst(room,g.x,g.y,'#ffd07f',36,315);shake=Math.max(shake,12);sound(110,.31,'sawtooth',.04);if(game.inHub&&room.dummy&&Math.hypot(room.dummy.x+room.dummy.w/2-g.x,room.dummy.y+room.dummy.h/2-g.y)<130)hitDummy(room,75,Math.sign(g.vx)||1);for(const e of room.enemies)if(e.alive&&Math.hypot(e.x+e.w/2-g.x,e.y+e.h/2-g.y)<130)hitEnemy(room,e,75);for(const q of room.portals)if(q.alive&&Math.hypot(q.x-g.x,q.y-g.y)<125)hitPortal(room,q,70);const p=game.player;if(Math.hypot(p.x+p.w/2-g.x,p.y+p.h/2-g.y)<72)damagePlayer(9);}
function useAccessory(index){if(!game||paused||mapOpen)return;const p=game.player,a=p.accessories[index],spec=a&&ACCESSORIES[a.type];if(!spec){announce('ÖZEL EŞYA SLOTU BOŞ',.8);return;}if(a.cooldown>0){announce('EŞYA BEKLEME: '+Math.ceil(a.cooldown)+'sn',.9);return;}p.activeAccessory=a.type;p.accessoryTime=spec.duration;a.cooldown=spec.cooldown;burst(currentRoom(),p.x+p.w/2,p.y+p.h/2,spec.color,22,190);announce(spec.name+' AKTİV · '+spec.duration+'sn');updateHud();}
function grantAccessory(p,type){const idx=p.accessories.findIndex(a=>!a);if(idx<0)return false;p.accessories[idx]={type,cooldown:0};return true;}
function breakWeapon(){const p=game.player;if(p.weapon===null)return;cancelReload(p);saveSlot();const old=p.weapon;const other=p.slots.findIndex((q,i)=>i!==p.activeSlot&&q&&(q.ammo>0||q.reserve>0));if(other>=0){p.activeSlot=other;p.weapon=p.slots[other].weapon;p.ammo=p.slots[other].ammo;p.reserve=p.slots[other].reserve;announce('MERMİ BİTTİ · YEDEK SİLAHA GEÇİLDİ',1.65);}else announce('MERMİ BİTTİ · V İLE BIÇAK KULLAN · SİLAH ENVANTERDE',1.4);floating(p.x,p.y-22,weaponName(old),'#a8efff');sound(170,.17,'triangle');updateHud();}
function cancelReload(p){p.reloadTime=0;p.reloadDuration=0;p.reloadWeaponId=null;}
function reloadWeapon(){if(!game||paused||mapOpen)return;const p=game.player;if(p.reloadTime>0||p.weapon===null||p.reserve<=0)return;const st=weaponStats(p.slots[p.activeSlot]);if(p.ammo>=st.mag)return;p.reloadDuration=st.reload;p.reloadTime=p.reloadDuration;p.reloadWeaponId=p.weapon;shootTimer=Math.max(shootTimer,p.reloadDuration);announce('ŞARJÖR DOLDURULUYOR',p.reloadDuration);sound(470,.09,'triangle');updateHud();}
function finishReload(p){if(p.reloadWeaponId===null||p.reloadWeaponId===undefined)return;if(p.weapon===p.reloadWeaponId&&p.reserve>0){const need=Math.min(weaponStats(p.slots[p.activeSlot]).mag-p.ammo,p.reserve);p.ammo+=need;p.reserve-=need;saveSlot();announce('ŞARJÖR DOLDURULDU · '+p.ammo+'/'+p.reserve,.75);updateHud();}cancelReload(p);}
function melee(){
 const p=game.player,room=currentRoom(),now=game.elapsed;
 p.meleeCombo=now<(p.meleeUntil||0)?((p.meleeCombo||0)%3)+1:1;p.meleeUntil=now+.85;
 const combo=p.meleeCombo,range=combo===3?115:combo===2?102:92,damage=combo===3?57:combo===2?41:32;
 shootTimer=combo===3?.38:.235;const cx=p.x+p.w/2,cy=p.y+p.h*.48,dx=mouse.x-cx,dy=mouse.y-cy,len=Math.hypot(dx,dy)||1,ux=dx/len,uy=dy/len;
 p.face=ux>=0?1:-1;p.kick=.15;game.slash={x:cx,y:cy,angle:Math.atan2(dy,dx),time:combo===3?.34:.26,duration:combo===3?.34:.26,combo,range,hits:0};
 p.x=clamp(p.x+p.face*(combo===3?22:12),WALL+9,W-WALL-p.w-9);
 burst(room,cx+ux*42,cy+uy*42,combo===3?'#ffd68b':'#a3efff',combo===3?24:13,190);
 sound(combo===3?230:combo===2?375:470,.11,'sawtooth',.026);shake=Math.max(shake,combo===3?9:4);
 let hits=0;const inArc=(ex,ey,r)=>{const dist=Math.hypot(ex,ey);return dist<r&&(dist<30||(ex*ux+ey*uy)/(dist||1)>(combo===3?-.12:.1));};
 if(game.inHub&&room.dummy&&inArc(room.dummy.x+room.dummy.w/2-cx,room.dummy.y+room.dummy.h/2-cy,range))hitDummy(room,damage,p.face);for(const e of room.enemies){const ex=e.x+e.w/2-cx,ey=e.y+e.h/2-cy;if(e.alive&&inArc(ex,ey,range)){hitEnemy(room,e,damage,'melee');e.x=clamp(e.x+p.face*(combo===3?34:18),WALL+10,W-WALL-e.w-10);e.vx=p.face*210;e.vy=Math.min(e.vy,-105);hits++;}}
 for(const q of room.portals){const ex=q.x-cx,ey=q.y-cy;if(q.alive&&inArc(ex,ey,range))hitPortal(room,q,damage);}
 for(const c of room.crystals)if(c.alive&&Math.hypot(c.x-cx,c.y-cy)<range){c.hp-=damage;c.flash=.2;if(c.hp<=0)explodeCrystal(room,c);}
 for(const b of room.breakables)if(b.alive&&inArc(b.x+b.w/2-cx,b.y+b.h/2-cy,range)){hitBreakable(room,b,damage);}
 for(const o of room.props)if(o.alive&&inArc(o.x+o.w/2-cx,o.y+o.h/2-cy,range))hitProp(room,o,damage);
 if(game.slash)game.slash.hits=hits;if(hits){addFlow(hits*(combo===3?12:7),'MELEE');hitStop=combo===3?.06:.035;burst(room,cx+ux*range*.8,cy+uy*range*.8,'#fff4c9',combo===3?20:10,225);}
}

// Single weapon stat model shared by shot simulation, reload and both build screens.
const weaponStats=window.DropForgeWeaponStats.createWeaponStats({WEAPON_DAMAGE,WEAPON_FIRE_RATES,WEAPON_PROJECTILES,MAG_SIZE,getMasteryLevel:masteryLevel,getMasteryTalents:id=>talents[id]});
// Each of the 13 guns owns its own right-click ability and cooldown.
function abilityCooldown(p,weapon){return p?.abilityCooldowns?.[weapon]||0;}
function updateStatusStrip(){
 if(!game)return;const p=game.player,room=currentRoom(),status=$('statusMessage'),ability=$('abilityStatus');
 const message=announcement>0?announcementText:(game.inHub?'HAZIRLIK':'DERİNLİK '+room.y);if(status&&status.textContent!==message)status.textContent=message;
 if(ability){const spec=WEAPON_ABILITIES[p.weapon],value=spec?'↗ '+spec.name+' · '+(abilityCooldown(p,p.weapon)>0?abilityCooldown(p,p.weapon).toFixed(1)+'sn':'✓'):'↗ —';if(ability.textContent!==value)ability.textContent=value;ability.title=spec?.description||'Silahın yok';}
}
function specialBullet(p,st,angle,{family=st.family,damage=st.damage,speed=st.speed,pierces=st.pierce,areaBonus=st.areaBonus,impactStagger=st.staggerBonus,shotEffects={shockRemaining:1}}={}){
 const spec=PROJECTILE_FAMILIES[family];game.bullets.push({x:p.x+p.w/2,y:p.y+p.h*.45,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed,life:Math.max(spec.life,Math.hypot(W,H)/Math.max(1,speed)+.5),damage:Math.max(1,Math.round(damage)),mods:[...(p.slots[p.activeSlot].mods||[])],shotEffects,weapon:p.weapon,family,pierces,impactStagger,areaBonus,hitTargets:new Set(),radius:spec.radius});
}
function useWeaponAbility(){
 if(!game||paused||mapOpen||game.dead||game.won)return false;const p=game.player,id=p.weapon,spec=WEAPON_ABILITIES[id];if(!spec)return false;
 if(abilityCooldown(p,id)>0){announce(spec.name+' · '+Math.ceil(abilityCooldown(p,id))+'sn BEKLE',.7);return false;}
 const room=currentRoom(),st=weaponStats(p.slots[p.activeSlot]),x=p.x+p.w/2,y=p.y+p.h*.45,angle=Math.atan2(mouse.y-y,mouse.x-x),shared={shockRemaining:1};
 const bolt=(offset=0,multiplier=1,options={})=>specialBullet(p,st,angle+offset,{...options,damage:st.damage*multiplier,shotEffects:shared});
 if(id===0)for(const offset of [-.13,0,.13])bolt(offset,.95,{family:'kinetic'});
 else if(id===1)p.abilityBuff={weapon:id,time:2.2};
 else if(id===2){let hit=0;for(const e of room.enemies)if(e.alive&&Math.hypot(e.x+e.w/2-x,e.y+e.h/2-y)<195&&Math.abs(Math.atan2(Math.sin(Math.atan2(e.y+e.h/2-y,e.x+e.w/2-x)-angle),Math.cos(Math.atan2(e.y+e.h/2-y,e.x+e.w/2-x)-angle)))<1.2){hitEnemy(room,e,Math.round(st.shotDamage*.63),'ability',id);e.stagger=Math.max(e.stagger,.35);e.knockVx=Math.cos(angle)*280;hit++;}if(game.inHub&&room.dummy&&Math.hypot(room.dummy.x+room.dummy.w/2-x,room.dummy.y+room.dummy.h/2-y)<195)hitDummy(room,Math.round(st.shotDamage*.63),p.face);burst(room,x+Math.cos(angle)*85,y+Math.sin(angle)*85,'#b9edff',24,240);}
 else if(id===3)bolt(0,2.15,{family:'plasma',pierces:2,areaBonus:st.areaBonus*1.5});
 else if(id===4)bolt(0,2.05,{family:'pierce',pierces:5,speed:st.speed*1.2});
 else if(id===5)bolt(0,1.55,{family:'kinetic',impactStagger:3.2,pierces:1});
 else if(id===6)for(const offset of [-.17,0,.17])bolt(offset,1.05,{family:'plasma'});
 else if(id===7)for(let k=-4;k<=4;k++)bolt(k*.083,.65,{family:'scatter'});
 else if(id===8){const enemies=room.enemies.filter(e=>e.alive),target=enemies.sort((a,b)=>Math.hypot(a.x+a.w/2-mouse.x,a.y+a.h/2-mouse.y)-Math.hypot(b.x+b.w/2-mouse.x,b.y+b.h/2-mouse.y))[0];if(!target&&game.inHub&&room.dummy){room.dummy.markTime=5;burst(room,room.dummy.x+room.dummy.w/2,room.dummy.y,'#ffdc86',18,110);}else if(!target){announce('İŞARETLENECEK HEDEF YOK',.9);return false;}if(target){target.markTime=5;burst(room,target.x+target.w/2,target.y,'#ffdc86',22,125);floating(target.x,target.y-23,'İŞARETLENDİ · 5sn','#ffe39b');}}
 else if(id===9)for(const offset of [-.075,-.025,.025,.075])bolt(offset,.88,{family:'kinetic'});
 else if(id===10)for(const offset of [-.095,0,.095])bolt(offset,1.15,{family:'laser',pierces:2});
 else if(id===11)for(const offset of [-.25,0,.25])bolt(offset,.9,{family:'explosive',areaBonus:st.areaBonus*1.10});
 else if(id===12){let px=x,py=y,damage=st.damage*1.8;const remaining=room.enemies.filter(e=>e.alive);for(let i=0;i<4;i++){remaining.sort((a,b)=>Math.hypot(a.x+a.w/2-px,a.y+a.h/2-py)-Math.hypot(b.x+b.w/2-px,b.y+b.h/2-py));const e=remaining.shift();if(!e||Math.hypot(e.x+e.w/2-px,e.y+e.h/2-py)>275)break;hitEnemy(room,e,Math.round(damage),'ability',id);burst(room,e.x+e.w/2,e.y+e.h/2,'#a7f5ff',17,165);px=e.x+e.w/2;py=e.y+e.h/2;damage*=.77;}if(game.inHub&&room.dummy&&Math.hypot(room.dummy.x+room.dummy.w/2-x,room.dummy.y+room.dummy.h/2-y)<240)hitDummy(room,Math.round(st.damage*1.8),p.face);}
 p.abilityCooldowns[id]=spec.cooldown;p.kick=Math.max(p.kick,.18*st.recoil);shake=Math.max(shake,4);burst(room,x,y,PROJECTILE_FAMILIES[st.family].color,18,185);sound(540,.11,'triangle',.025);announce(spec.name+' · SAĞ TIK YETENEĞİ',1.5);updateStatusStrip();return true;
}
function fire(){if(!game||paused||mapOpen||game.dead||game.won||shootTimer>0)return;const p=game.player,weapon=p.weapon;if(weapon===null){announce('V · BIÇAK KULLAN',.65);return;}if(p.ammo<=0){if(p.reserve>0)reloadWeapon();else if((p.emptyWarningTime||0)<=0){breakWeapon();p.emptyWarningTime=2.8;shootTimer=.38;}else shootTimer=.3;return;}const stForAmmo=weaponStats(p.slots[p.activeSlot]);if(Math.random()>=Math.min(.8,(stForAmmo.ammoSave||0)+gearStats().ammo))p.ammo--;p.slots[p.activeSlot].ammo=p.ammo;shootTimer=stForAmmo.interval*(p.abilityBuff?.weapon===weapon&&p.abilityBuff.time>0?.67:1);const st=stForAmmo,dx=mouse.x-(p.x+p.w/2),dy=mouse.y-(p.y+p.h*.45),base=Math.atan2(dy,dx),family=st.family,spec=PROJECTILE_FAMILIES[family],count=st.pellets;
 const shotEffects={shockRemaining:1};for(let i=0;i<count;i++){const spread=(family==='scatter'?.12:.025)*st.spread,ang=base+(i-(count-1)/2)*spread+(Math.random()-.5)*.027*st.spread,speed=st.speed;game.bullets.push({x:p.x+p.w/2,y:p.y+p.h*.45,vx:Math.cos(ang)*speed,vy:Math.sin(ang)*speed,life:Math.max(spec.life,Math.hypot(W,H)/Math.max(1,speed)+.5),damage:Math.round(st.damage*((p.grapple||p.dash>0||p.moveCharge>0)?1+st.movementBonus:1)),mods:[...p.slots[p.activeSlot].mods],shotEffects,weapon,family,pierces:st.pierce,impactStagger:st.staggerBonus,areaBonus:st.areaBonus,hitTargets:new Set(),radius:spec.radius});}
 p.face=dx>=0?1:-1;p.kick=(family==='explosive'?.24:family==='scatter'?.2:.12)*st.recoil;shake=Math.max(shake,family==='explosive'?8:family==='scatter'?5:2);flash=Math.max(flash,family==='explosive'?.13:.055);flashTint='255,235,211';game.muzzleFlash={x:p.x+p.w/2+Math.cos(base)*35,y:p.y+p.h*.45+Math.sin(base)*35,color:spec.color,time:.11};sound(family==='plasma'?375:family==='scatter'?105:215,.065,family==='plasma'?'sine':'square',.02);burst(currentRoom(),p.x+p.w/2+Math.cos(base)*25,p.y+p.h*.45+Math.sin(base)*25,spec.color,family==='explosive'?19:family==='scatter'?12:7,150);burst(currentRoom(),p.x+p.w/2+Math.cos(base)*34,p.y+p.h*.45+Math.sin(base)*34,'#fff4ce',family==='explosive'?10:4,95);if(!p.ammo&&!p.reserve)breakWeapon();else updateHud();}
// Plasma has a small splash. Piercing rounds may pass through one target before disappearing.
function applyProjectileModEffects(room,e,b){if(!e.alive&&!b.mods?.includes('shockCore'))return;if(e.alive&&b.mods?.includes('burnCore')){e.burnTime=3;e.burnTick=.5;e.burnDamage=Math.max(1,Math.round(b.damage*.12));burst(room,e.x+e.w/2,e.y+e.h/2,'#ffb46e',7,80);}if(b.mods?.includes('shockCore')&&(b.shotEffects?.shockRemaining??1)>0){const other=room.enemies.find(q=>q!==e&&q.alive&&!b.hitTargets.has(q)&&Math.hypot(q.x-e.x,q.y-e.y)<140);if(other){if(b.shotEffects)b.shotEffects.shockRemaining--;b.hitTargets.add(other);const amount=Math.max(1,Math.round(b.damage*.35));burst(room,other.x+other.w/2,other.y+other.h/2,'#a0f0ff',12,160);hitEnemy(room,other,amount,'shock',b.weapon);}}}
function projectileImpact(room,b,x=b.x,y=b.y){const spec=PROJECTILE_FAMILIES[b.family]||PROJECTILE_FAMILIES.kinetic;burst(room,x,y,spec.color,['plasma','explosive','arc'].includes(b.family)?12:4,['plasma','explosive','arc'].includes(b.family)?160:80);if(!['plasma','explosive','arc'].includes(b.family))return;const range=Math.round((b.family==='explosive'?104:b.family==='arc'?77:52)*(b.areaBonus||1)),damage=Math.max(5,Math.round(b.damage*(b.family==='explosive'?.76:b.family==='arc'?(b.mods?.includes('core')?.75:.5):.38)));if(b.family==='explosive'){shake=Math.max(shake,8);burst(room,x,y,'#ffb36d',30,260);sound(92,.21,'sawtooth',.042);}if(b.family==='arc'){burst(room,x,y,'#9df4ff',16,180);}for(const e of room.enemies)if(e.alive&&!b.hitTargets.has(e)&&Math.hypot(e.x+e.w/2-x,e.y+e.h/2-y)<range){b.hitTargets.add(e);hitEnemy(room,e,damage,'plasma');applyProjectileModEffects(room,e,b);}for(const q of room.portals)if(q.alive&&!b.hitTargets.has(q)&&Math.hypot(q.x-x,q.y-y)<range){b.hitTargets.add(q);hitPortal(room,q,damage);}}

function hitEnemy(room,e,amount,source='bullet',weapon=null){if(source==='bullet')addFlow(4,'HIT');const shieldAbsorbed=Math.min(e.shield||0,amount);if(shieldAbsorbed){e.shield-=shieldAbsorbed;amount-=shieldAbsorbed;floating(e.x+e.w/2,e.y-25,'KALKAN -'+shieldAbsorbed,'#8adfff');}if(amount<=0){e.hit=.12;burst(room,e.x+e.w/2,e.y+e.h*.45,'#8adfff',8,115);return;}const dealt=Math.min(e.hp,amount);if(weapon!==null&&!game.inHub&&dealt>0){e.weaponDamage??={};e.weaponDamage[weapon]=(e.weaponDamage[weapon]||0)+dealt;room.weaponDamage??={};room.weaponDamage[weapon]=(room.weaponDamage[weapon]||0)+dealt;e.xpHitClock??={};if((game.elapsed-(e.xpHitClock[weapon]??-10))>=.22){grantMastery(weapon,2+(game.flow>=65?1:0));e.xpHitClock[weapon]=game.elapsed;}}e.hp-=amount;e.hit=.18;const knockDir=game.player.x+game.player.w/2<e.x+e.w/2?1:-1;e.stagger=e.type==='boss'?.045:.105;e.knockVx=knockDir*Math.min(e.type==='boss'?75:210,60+amount*2.2);e.hitFacing=knockDir;burst(room,e.x+e.w/2,e.y+e.h*.45,e.type==='red'?'#ff6c79':e.type==='blue'?'#69d5ff':'#d595ff',10,175);burst(room,e.x+e.w/2,e.y+e.h*.45,'#fff4da',5,95);floating(e.x+e.w/2,e.y-10,String(amount),'#ffe9b1');hitStop=.025;shake=Math.max(shake,3);sound(95,.045,'triangle',.025);if(e.hp<=0){if(!game.inHub&&e.weaponDamage){const total=Object.values(e.weaponDamage).reduce((a,b)=>a+b,0);for(const [id,damage] of Object.entries(e.weaponDamage))grantMastery(Number(id),Math.max(1,Math.round((e.type==='boss'?27:e.type==='brute'?20:12)*damage/total)));}killEnemy(room,e);}}
function hitPortal(room,q,amount){if(q.shield>0){burst(room,q.x,q.y,'#8bdeff',4,100);floating(q.x,q.y-45,'KALKAN','#a9eaff');return;}q.hp=Math.max(0,q.hp-amount);q.regenDelay=5;q.regenBase=q.hp;q.regenCap=Math.min(q.maxHp,q.regenBase*1.3);if(q.hp>0&&q.shieldCharges>0&&q.hp<=q.maxHp*(q.shieldCharges===2?.7:.5)){q.shieldCharges--;q.shieldTriggered=true;q.shield=2.7;q.overdrive=true;q.time=Math.max(q.time,q.shield);floating(q.x,q.y-64,'PORTAL KALKANI · '+q.shieldCharges+' HAK KALDI','#a9eaff');announce('PORTAL SAVUNMAYA GEÇTİ · ARDINDAN HIZLI ÜRETİM',2.5);sound(690,.16,'triangle');}q.hit=.18;burst(room,q.x,q.y,'#d59cff',8,125);floating(q.x,q.y-40,String(amount),'#d9b8ff');shake=Math.max(shake,3);if(q.hp<=0){q.alive=false;burst(room,q.x,q.y,'#b889fb',25,300);dropPickup(room,Math.random()<.78?'health':'ammo',q.x,q.y,Math.random()<.08);floating(q.x,q.y-60,'PORTAL KIRILDI','#d6b7ff');sound(135,.24,'sawtooth');}}
