function damagePlayer(amount){const p=game.player;if(game.testMode){p.hp=Math.max(1,p.hp-Math.max(1,Math.round(amount*game.settings.enemyDamage)));if(p.hp<=1){p.hp=p.maxHp;p.invuln=1.5;announce('TEST · CAN YENİLENDİ',1.5);}return;}if(p.invuln>0||game.dead)return;if(p.activeAccessory==='shield'&&p.accessoryTime>0){burst(currentRoom(),p.x+p.w/2,p.y+p.h/2,'#a4e7ff',11,130);p.invuln=.25;return;}amount=Math.max(1,Math.round(amount*game.settings.enemyDamage));p.hp=Math.max(0,p.hp-amount);if(p.hp>0&&p.hp<p.maxHp*.5&&p.kits>0&&!nearbyGroundKit(currentRoom(),p))useKit(true);game.flow=Math.max(0,(game.flow||0)-18);game.flowChain=0;p.invuln=.8;shake=12;flash=.22;flashTint='255,95,109';hitStop=.045;burst(currentRoom(),p.x+p.w/2,p.y+p.h/2,'#ff7c85',16,205);floating(p.x,p.y-25,'-'+amount+' CAN','#ff9292');sound(130,.18,'sawtooth');if(p.hp===0){game.dead=true;paused=true;showEnd(false);}updateHud();}
