function drawPortal(q){
 ctx.save();ctx.translate(q.x,q.y);
 const col=({red:'#ff6469',blue:'#60b7ff',purple:'#d18dff',healer:'#72e8a9'})[q.type]||'#bf86f9';
 const biomeCol=BIOMES[q.biome||'cave'].accent,t=(game?.elapsed||0),active=q.shield>0;
 // Anchored pixel-art stone frame with cycling energy channels.
 ctx.fillStyle='#15172a';ctx.fillRect(-28,-32,56,66);
 ctx.fillStyle=biomeCol;for(let k=0;k<4;k++){const yy=-29+k*16;ctx.fillRect(-29,yy,7,7);ctx.fillRect(22,yy,7,7);}
 ctx.fillStyle='#35354c';ctx.fillRect(-31,-36,62,7);ctx.fillRect(-31,30,62,8);
 for(let k=0;k<9;k++){const a=t*(active?-2:1.7)+k*Math.PI*2/9;const rr=active?27:20;ctx.globalAlpha=.4+.5*(.5+.5*Math.sin(t*3+k));ctx.fillStyle=active?'#a4efff':col;ctx.fillRect(Math.round(Math.cos(a)*rr)-2,Math.round(Math.sin(a)*rr*1.38)-2,4,4);}ctx.globalAlpha=1;
 ctx.save();ctx.beginPath();ctx.ellipse(0,0,18,26,0,0,Math.PI*2);ctx.clip();
 const gradient=ctx.createLinearGradient(-18,-27,18,27);gradient.addColorStop(0,'#110e25');gradient.addColorStop(.5,col);gradient.addColorStop(1,'#17102a');ctx.globalAlpha=.86;ctx.fillStyle=gradient;ctx.fillRect(-20,-28,40,56);ctx.globalAlpha=1;
 ctx.strokeStyle='#f4e8ff';ctx.lineWidth=2;for(let k=0;k<3;k++){const y=((t*33+k*24)%75)-37;ctx.beginPath();ctx.moveTo(-18,y);ctx.lineTo(18,y-12);ctx.stroke();}ctx.restore();
 ctx.strokeStyle=q.hit>0?'#ffffff':active?'#a1eeff':col;ctx.lineWidth=5;ctx.shadowColor=ctx.strokeStyle;ctx.shadowBlur=active?21:13;ctx.beginPath();ctx.ellipse(0,0,20,28,0,0,Math.PI*2);ctx.stroke();ctx.shadowBlur=0;
 if(active){ctx.strokeStyle='#c1f8ff';ctx.lineWidth=2;ctx.setLineDash([7,5]);ctx.lineDashOffset=-t*32;ctx.beginPath();ctx.ellipse(0,0,31,39,0,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);}
 ctx.fillStyle='#11111e';ctx.fillRect(-32,-50,64,8);ctx.fillStyle=q.hp/q.maxHp>.35?col:'#ff7284';ctx.fillRect(-30,-48,60*clamp(q.hp/q.maxHp,0,1),4);ctx.strokeStyle='#bdc3db';ctx.lineWidth=1;ctx.strokeRect(-32,-50,64,8);
 ctx.textAlign='center';ctx.font='bold 10px monospace';ctx.fillStyle='#f3e7ff';ctx.fillText(VARIANTS[q.biome||'cave'][q.type]+' '+Math.ceil(q.hp)+'/'+q.maxHp,0,-57);
  const spawnRemaining=Math.max(0,q.time),spawnDuration=Math.max(.1,q.spawnDuration||game.settings.spawnDelay),progress=clamp(1-spawnRemaining/spawnDuration,0,1);
  const spawnLabel=spawnRemaining>0?'SPAWN '+spawnRemaining.toFixed(1)+'s':'SPAWN HAZIR';
  ctx.fillStyle='#071629';ctx.fillRect(-29,42,58,17);ctx.fillStyle='#9de9ff';ctx.font='bold 9px monospace';ctx.fillText(spawnLabel,0,51);
  ctx.fillStyle='#344b67';ctx.fillRect(-27,54,54,3);ctx.fillStyle=spawnRemaining>0?'#7bd2ff':'#a8f0a4';ctx.fillRect(-27,54,54*progress,3);
 if(active){ctx.fillStyle='#a8efff';ctx.fillText('KALKAN '+q.shield.toFixed(1)+'s',0,-72);}
 else if(q.shieldCooldown>0){ctx.fillStyle='#acbad0';ctx.fillText('KALKAN BEKLEME '+Math.ceil(q.shieldCooldown)+'s',0,-72);ctx.fillStyle='#384659';ctx.fillRect(-23,-67,46,3);ctx.fillStyle='#66bbd4';ctx.fillRect(-23,-67,46*(1-q.shieldCooldown/15),3);}
 else if(q.regenDelay===0&&q.hp<(q.regenCap??q.maxHp)){ctx.fillStyle='#a4ffd3';ctx.fillText('YENİLENİYOR',0,-72);}
 ctx.restore();
}
const {drawChest,drawBreakable,drawProp,drawLoot}=window.DropForgeLootView.createLootRenderer({ctx,currentRoom,ACCESSORIES,WEAPON_SPRITES,weaponName});
function drawCrosshair(){if(game?.player?.reloadTime>0){const p=game.player,progress=1-p.reloadTime/Math.max(.01,p.reloadDuration),t=performance.now()/1000;ctx.save();ctx.strokeStyle='#ffd572';ctx.lineWidth=4;ctx.shadowColor='#ffbe55';ctx.shadowBlur=13;ctx.beginPath();ctx.arc(mouse.x,mouse.y,20,-Math.PI/2,-Math.PI/2+Math.PI*2*progress);ctx.stroke();ctx.shadowBlur=0;for(let i=0;i<4;i++){const a=t*3+i*Math.PI/2;ctx.fillStyle='#ffcf7e';ctx.fillRect(mouse.x+Math.cos(a)*27-2,mouse.y+Math.sin(a)*27-2,4,4);}ctx.restore();}ctx.strokeStyle='#fff2cd';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(mouse.x,mouse.y,8,0,Math.PI*2);ctx.moveTo(mouse.x-15,mouse.y);ctx.lineTo(mouse.x-10,mouse.y);ctx.moveTo(mouse.x+10,mouse.y);ctx.lineTo(mouse.x+15,mouse.y);ctx.moveTo(mouse.x,mouse.y-15);ctx.lineTo(mouse.x,mouse.y-10);ctx.moveTo(mouse.x,mouse.y+10);ctx.lineTo(mouse.x,mouse.y+15);ctx.stroke();}
function drawFollowingKeys(room){
 if(game.inHub||!room.cleared||!game.keyFollowers?.length)return;
 ctx.save();for(let i=0;i<game.keyFollowers.length;i++){const key=game.keyFollowers[i],leader=i?game.keyFollowers[i-1]:{x:game.player.x+game.player.w/2,y:game.player.y+game.player.h/2-20};ctx.strokeStyle='rgba(255,220,140,.48)';ctx.lineWidth=2;ctx.setLineDash([3,5]);ctx.beginPath();ctx.moveTo(leader.x,leader.y);ctx.lineTo(key.x,key.y);ctx.stroke();ctx.setLineDash([]);ctx.translate(key.x,key.y);ctx.rotate(Math.sin(game.elapsed*2+i)*.12);ctx.fillStyle='#ffe49b';ctx.strokeStyle='#a76c35';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,7,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#1d2940';ctx.beginPath();ctx.arc(0,0,3,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ffe49b';ctx.fillRect(5,-2,17,5);ctx.fillRect(16,2,4,6);ctx.fillRect(10,2,4,5);ctx.rotate(-Math.sin(game.elapsed*2+i)*.12);ctx.translate(-key.x,-key.y);}ctx.restore();
}
function drawNearbyMinimap(room){
 if(game.inHub||room.arenaStarted&&!room.cleared||room.enemies.some(e=>e.alive)||room.portals.some(q=>q.alive))return;
 const size=26,cx=W-106,cy=141,neighbors=Object.values(room.links).map(id=>game.rooms[id]).filter(Boolean),visible=[room,...neighbors],seen=new Set(visible.map(r=>r.id));
 ctx.save();ctx.globalAlpha=.76;ctx.fillStyle='#091422';ctx.fillRect(W-198,89,184,106);ctx.strokeStyle='#53738b';ctx.lineWidth=1;ctx.strokeRect(W-198,89,184,106);ctx.textAlign='left';ctx.fillStyle='#a8c9d7';ctx.font='bold 10px monospace';ctx.fillText('YAKIN ÇEVRE',W-188,104);
 for(const next of neighbors){const x=cx+(next.x-room.x)*size,y=cy+(next.y-room.y)*size;ctx.strokeStyle='#7895a6';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(cx,cy);ctx.lineTo(x,y);ctx.stroke();}
 for(const next of visible){if(!seen.has(next.id))continue;const x=cx+(next.x-room.x)*size,y=cy+(next.y-room.y)*size,active=next.id===room.id;ctx.fillStyle=active?'#f9e3a0':next.cleared?'#7dc5a5':next.type==='boss'?'#ad8cd5':'#7492ad';ctx.fillRect(x-7,y-7,14,14);ctx.strokeStyle=active?'#ffffff':'#b2c7d2';ctx.strokeRect(x-7,y-7,14,14);if(active){ctx.fillStyle='#152239';ctx.font='bold 12px monospace';ctx.textAlign='center';ctx.fillText('●',x,y+4);}}
 ctx.restore();
}
function drawGameHud(){const room=currentRoom();if(game.inHub)return;const flow=game.flow||0;ctx.fillStyle='#102033';ctx.fillRect(16,67,190,13);ctx.fillStyle=flow>70?'#ffe097':'#7de1bd';ctx.fillRect(18,69,186*flow/100,9);ctx.strokeStyle='#91b5cc';ctx.strokeRect(16,67,190,13);ctx.textAlign='left';ctx.font='bold 10px monospace';ctx.fillStyle='#e5ffe9';ctx.fillText('FORGE FLOW '+Math.round(flow)+'%',18,63);if(room.stage===1){ctx.fillStyle=game.bossKeys===3?'#b9ffbd':'#ffe49a';ctx.font='bold 12px monospace';ctx.textAlign='right';ctx.fillText('BOSS ANAHTARI '+game.bossKeys+'/3'+(game.bossKeys===3?' · KAPI AÇIK':''),W-24,60);ctx.textAlign='left';}if(!room.cleared&&room.arenaStarted){ctx.textAlign='right';ctx.font='bold 11px monospace';ctx.fillStyle=room.threatLevel>=2?'#ff9d75':'#ffe3a1';ctx.fillText('TEHDİT '+(room.threatLevel||0)+'/3 · '+Math.floor(room.threatTime||0)+'sn',W-24,79);ctx.textAlign='left';}if(!room.cleared){ctx.fillStyle='#e9a0a0';ctx.font='bold 12px system-ui';ctx.textAlign='center';ctx.fillText('⚔ ARENA KİLİTLİ · '+room.portals.filter(q=>q.alive).length+' PORTAL · '+room.enemies.length+' DÜŞMAN',W/2,59);ctx.textAlign='left';}if(room.generator){ctx.textAlign='center';ctx.font='bold 12px monospace';ctx.fillStyle=room.generator.failed?'#ff928d':'#a7f5c2';ctx.fillText(room.generator.failed?'SAVUNMA BAŞARISIZ':'JENERATÖR '+room.generator.hp+' CAN · '+Math.ceil(room.generator.time)+'sn',W/2,79);ctx.textAlign='left';}if(room.type==='hunt'&&!room.cleared){ctx.font='bold 12px monospace';ctx.fillStyle='#ffe09c';ctx.textAlign='center';ctx.fillText(room.enemies.some(e=>e.hunted&&e.alive)?'HEDEFİ YOK ET · PORTALLARI KAPAT':'HEDEF DÜŞTÜ · DÜŞMANLARI TEMİZLE',W/2,79);ctx.textAlign='left';}if(room.type==='boss'&&room.enemies.length){ctx.textAlign='center';ctx.font='bold 12px monospace';ctx.fillStyle='#ffcf99';ctx.fillText('BOSS '+room.bossStage+'/4 · '+(room.enemies.find(e=>e.type==='boss')?.bossName||BIOMES[room.biome].name)+' · FAZ '+(room.enemies.find(e=>e.type==='boss')?.bossPhase||1)+'/2',W/2,101);ctx.textAlign='left';let e=room.enemies.find(e=>e.type==='boss');if(e){ctx.fillStyle='#1b1524';ctx.fillRect(290,83,540,12);ctx.fillStyle='#b57db9';ctx.fillRect(290,83,540*(e.hp/e.maxHp),12);ctx.strokeStyle='#cda5c8';ctx.strokeRect(290,83,540,12);}}}
function updateHud(){
 if(!game)return;const p=game.player;
 $('hpFill').style.width=(p.hp/p.maxHp*100)+'%';$('hpText').textContent=p.hp+' / '+p.maxHp;
 $('weaponLabel').textContent=weaponName(p.weapon);$('weaponTypeLabel').textContent=weaponType(p.weapon);
 $('hudXp').innerHTML=p.weapon===null?'':xpBarHTML(p.weapon);
 $('ammoText').textContent=p.weapon===null?'—':p.ammo+' / '+p.reserve;
 $('roomLabel').textContent=game.inHub?'HAZIRLIK':String(game.roomId+1).padStart(2,'0')+' / '+game.rooms.length;
 $('goldLabel').textContent=p.gold;
 updateStatusStrip();
 for(let i=0;i<2;i++){const slot=p.slots[i];renderQuickSlot(i+1,slot?{weapon:slot.weapon,name:weaponName(slot.weapon),sub:slot.ammo+' / '+slot.reserve+' MERMİ',selected:p.activeSlot===i}:{name:'BOŞ SİLAH',sub:'Silah yok',empty:true});}
 renderQuickSlot(3,{name:'SAĞLIK KİTİ',sub:p.kits?'Kullanıma hazır':'Stokta yok',count:p.kits+'/5',icon:'kit',empty:!p.kits});
 renderQuickSlot(4,{name:'EL BOMBASI',sub:p.grenades?'Atışa hazır':'Stokta yok',count:p.grenades+'/3',icon:'grenade',empty:!p.grenades});
 const a=p.accessories[0];renderQuickSlot(5,a?{name:ACCESSORIES[a.type].name,sub:a.cooldown>0?'BEKLE '+Math.ceil(a.cooldown)+'sn':'HAZIR',count:'1',icon:a.type,selected:p.activeAccessory===a.type&&p.accessoryTime>0}:{name:'ÖZEL EŞYA',sub:'Boş',icon:'empty',empty:true});
}
function showEnd(won){$('gamePauseMenu').classList.add('hidden');$('pause').classList.remove('hidden');$('pause').querySelector('.eyebrow').textContent=won?'MAĞARA TEMİZLENDİ':'MACERA SONA ERDİ';$('pause').querySelector('h1').innerHTML=won?'ZAFER <em>!</em>':'OYUN <em>BİTTİ</em>';$('pause').querySelector('p').textContent='Altın: '+game.player.gold+' · Yenilen düşman: '+game.player.kills+' · Keşfedilen oda: '+game.rooms.filter(r=>r.visited).length+'/'+game.rooms.length;$('startBtn').textContent='YENİ OYUN →';$('seedInput').value=String(game.seed);$('forgePanel').classList.remove('hidden');refreshForge();}
let loadoutOpen=false,levelToastTime=0;
function levelUpToast(weapon,level){const el=$('levelToast');el.textContent='★ SİLAH USTALIĞI ARTTI ★\n'+weaponName(weapon)+' · SEVİYE '+level+(level===2||level===4||level===6||level===8?'\nYENİ EKLENTİ YUVASI AÇILDI!':'');el.classList.remove('hidden');levelToastTime=3.2;sound(790,.18,'triangle',.035);}
function gearPieceBonus(item){if(!item)return 'EKİPMAN YOK';const spec=GEAR.SETS[item.set];return [spec.hp?'+'+spec.hp+' MAKS. CAN':'',spec.speed?'+%'+Math.round(spec.speed*1000)/10+' HIZ':'',spec.ammo?'+%'+Math.round(spec.ammo*1000)/10+' MERMİ TASARRUFU':'',spec.leech?'+'+spec.leech+' CAN / ÖLDÜRME':''].filter(Boolean).join(' · ');}
function gearSlotsHTML(p,editable=false){return GEAR.SLOTS.map(slot=>{const item=p.equipment[slot],set=item&&GEAR.SETS[item.set],selected=editable&&activeGearSlot===slot;return '<div class="gearVisualSlot'+(item?' equipped':' empty')+(selected?' selected':'')+'" style="--gear-color:'+(set?.color||'#688198')+'">'+(editable?'<button type="button" class="gearSlotSelect" data-select-gear-slot="'+slot+'" aria-pressed="'+selected+'">':'<div class="gearSlotReadOnly">')+'<span class="gearIcon">'+(item?'<img alt="'+GEAR.SLOT_NAMES[slot]+'" src="'+GEAR.icon(item)+'">':'<span class="gearEmptySquare" aria-hidden="true"></span>')+'</span><span class="gearSlotDetails"><b>'+GEAR.SLOT_NAMES[slot]+'</b><small>'+(set?set.name:'BOŞ YUVA · SEÇ')+'</small><span class="gearPieceBonus">'+gearPieceBonus(item)+'</span></span>'+(editable?'</button>':'</div>')+(item?'<button type="button" data-unequip-gear="'+slot+'">ÇIKAR</button>':'')+'</div>';}).join('');}
function gearSummaryHTML(st){return '<div class="gearSummary"><b>TOPLAM EKİPMAN KATKISI</b><span>+'+st.hp+' MAKS. CAN</span><span>+%'+Math.round(st.speed*100)+' HIZ</span><span>+%'+Math.round(st.ammo*100)+' MERMİ TASARRUFU</span><span>+'+st.leech+' CAN / ÖLDÜRME</span><small>SET BONUSU: '+(st.full.length?st.full.map(id=>GEAR.SETS[id].bonus).join(' · '):'5 AYNI SET PARÇASI KUŞAN')+'</small></div>';}
function gearEquipmentHTML(p,st,editable=false){return '<div class="gearEquipmentLayout"><div class="gearCharacterPanel"><b>KARAKTER</b><canvas class="gearCharacterCanvas" width="144" height="224" role="img" aria-label="Kuşanılmış zırhlarla karakter görünümü"></canvas><small>'+GEAR.SLOTS.filter(slot=>p.equipment[slot]).length+'/5 PARÇA KUŞANILDI</small></div><div class="gearEquipmentRight"><b>KUŞANILAN SET · 5 YUVA</b><div class="gearVisualGrid">'+gearSlotsHTML(p,editable)+'</div>'+gearSummaryHTML(st)+'</div></div>';}
function drawGearPreview(root,p){const canvas=root.querySelector('.gearCharacterCanvas');if(!canvas)return;const c=canvas.getContext('2d');c.clearRect(0,0,canvas.width,canvas.height);c.imageSmoothingEnabled=false;c.save();c.translate(72,120);c.scale(2.55,2.55);GEAR.drawWarrior(c,p.equipment);c.restore();}
function gearBagHTML(p){return p.gearBag.map(item=>'<button type="button" class="gearItem" data-gear="'+item.id+'"><img alt="'+GEAR.SLOT_NAMES[item.slot]+'" src="'+GEAR.icon(item)+'"><span><b>'+GEAR.SETS[item.set].name+'</b><small>'+GEAR.SLOT_NAMES[item.slot]+' · KUŞAN</small></span></button>').join('')||'<p>Çantada zırh yok. Seferde zırh toplayabilirsin.</p>';}
let activeGearSlot=null;
function gearSlotChoicesHTML(p){if(!activeGearSlot)return '';const choices=[...gearLocker].filter(id=>id.endsWith('-'+activeGearSlot));return '<div class="gearSlotChoices"><div class="gearSlotChoicesHead"><b>'+GEAR.SLOT_NAMES[activeGearSlot]+' · SEÇ</b><button type="button" data-close-gear-slot aria-label="Seçimi kapat">✕</button></div><div class="gearItemGrid">'+(choices.map(id=>{const set=id.slice(0,id.lastIndexOf('-')),item=GEAR.createGear(set,activeGearSlot),selected=p.equipment[activeGearSlot]?.id===id;return '<button type="button" class="gearItem'+(selected?' chosen':'')+'" data-locker-gear="'+id+'" aria-pressed="'+selected+'"><img alt="'+GEAR.SLOT_NAMES[activeGearSlot]+'" src="'+GEAR.icon(item)+'"><span><b>'+GEAR.SETS[set].name+'</b><small>'+gearPieceBonus(item)+'</small><small>'+(selected?'TAKILI · ÇIKAR':'KUŞAN')+'</small></span></button>';}).join('')||'<p>Bu yuvada zırh yok. Seferde buldukça açılır.</p>')+'</div></div>';}
function renderGearWorkbench(){const root=$('forgeGearContent');if(!root)return;const p=game?.inHub?game.player:{equipment:savedGearEquipment(),gearBag:[]},st=GEAR.stats(p.equipment);root.innerHTML=gearEquipmentHTML(p,st,true)+gearSlotChoicesHTML(p);drawGearPreview(root,p);}
function renderLoadout(){if(!game)return;saveSlot();const p=game.player,root=$('loadoutContent');root.innerHTML='';for(let i=0;i<2;i++){const w=p.slots[i],card=document.createElement('section');card.className='gunCard';if(!w){card.innerHTML='<h3>SİLAH '+(i+1)+' · BOŞ</h3><p>Bu slotta silah bulunmuyor.</p>';root.append(card);continue;}const picture=WEAPON_SPRITES[w.weapon].toDataURL('image/png');card.innerHTML='<h3>SİLAH '+(i+1)+' · '+weaponType(w.weapon)+'</h3><div class="gunVisual"><img alt="'+weaponName(w.weapon)+' piksel silah görseli" src="'+picture+'"><div><strong>'+weaponName(w.weapon)+'</strong><small>'+PROJECTILE_FAMILIES[WEAPON_PROJECTILES[w.weapon]].name+' · '+w.ammo+'/'+w.reserve+' MERMİ</small>'+xpBarHTML(w.weapon)+'</div></div><div class="weaponAbilityBadge"><b>SAĞ TIK · '+WEAPON_ABILITIES[w.weapon].name+'</b><small>'+WEAPON_ABILITIES[w.weapon].description+' · '+WEAPON_ABILITIES[w.weapon].cooldown+'sn bekleme</small></div><details class="advancedStats"><summary>AYRINTILI İSTATİSTİKLER</summary>'+weaponStatHTML(w)+'</details>'+talentHTML(w.weapon);for(let j=0;j<4;j++){const row=document.createElement('label');row.className='modRow'+(j>=getModSlots(w.weapon)?' locked':'');const select=document.createElement('select');select.dataset.weaponSlot=String(i);select.dataset.modSlot=String(j);select.disabled=j>=getModSlots(w.weapon);const current=w.mods[j]||'';let options='<option value="">'+(select.disabled?'KİLİTLİ · SEV '+([2,4,6,8][j]):'BOŞ EKLENTİ')+'</option>';for(const [id,spec] of Object.entries(MODS)){if(spec.slot===j&&(id===current||game.stashedMods.includes(id)))options+='<option value="'+id+'" '+(id===current?'selected':'')+'>'+modNameForWeapon(w.weapon,id)+(id===current?' · TAKILI':' · ÇANTADA')+'</option>';}select.innerHTML=options;row.innerHTML='<span>'+FORGE_SLOT_LABELS[j]+'</span>';row.append(select);const hint=document.createElement('small');hint.className='modBagHint';hint.textContent=current?modEffectForWeapon(w.weapon,current):j>=getModSlots(w.weapon)?'Sev '+[2,4,6,8][j]+' gerekli.':'Eklenti seç.';row.append(hint);card.append(row);}root.append(card);}const bag=document.createElement('section');bag.className='bagCard';bag.innerHTML='<h3>ÇANTA</h3><div class="bagItems"></div>';const bagItems=bag.querySelector('.bagItems');const pieces=['SAĞLIK KİTİ ×'+p.kits,'BOMBA ×'+p.grenades,'MERMİ KUTUSU ×'+p.ammoBoxes,...p.accessories.filter(Boolean).map(a=>ACCESSORIES[a.type].name),...game.stashedMods.map(m=>MODS[m]?.name||m)];for(const name of pieces){const chip=document.createElement('span');chip.className='bagChip';chip.textContent=name;bagItems.append(chip);}if(!game.stashedMods.length){const chip=document.createElement('span');chip.className='bagChip';chip.textContent='BOŞTA EKLENTİ YOK';bagItems.append(chip);}root.append(bag);const gear=document.createElement('section');gear.className='bagCard gearCard';const st=gearStats();gear.innerHTML='<h3>ZIRH · 5 YUVA</h3>'+gearEquipmentHTML(p,st)+'<h3>ZIRH ÇANTASI · '+p.gearBag.length+'/20</h3><div class="gearItemGrid">'+gearBagHTML(p)+'</div>';root.append(gear);drawGearPreview(gear,p);root.insertAdjacentHTML('beforeend',enemyCodexHTML());}
function switchModFromBag(select){if(!game)return;const i=Number(select.dataset.weaponSlot),j=Number(select.dataset.modSlot),w=game.player.slots[i],next=select.value,old=w?.mods[j]||'';if(!w||j>=getModSlots(w.weapon)||next===old)return;if(next&&(!MODS[next]||masteryLevel(w.weapon)<MODS[next].level||!game.stashedMods.includes(next)||MODS[next].slot!==j||w.mods.includes(next))){renderLoadout();return;}if(next)game.stashedMods.splice(game.stashedMods.indexOf(next),1);if(old)game.stashedMods.push(old);w.mods[j]=next||undefined;const cap=weaponStats(w).mag;if(w.ammo>cap){w.reserve=Math.min(AMMO_MAX[w.weapon],w.reserve+w.ammo-cap);w.ammo=cap;}if(game.player.activeSlot===i){game.player.ammo=w.ammo;game.player.reserve=w.reserve;}renderLoadout();updateHud();}
function toggleLoadout(force){if(shopOpen||hubForgeOpen||helpOpen||!game||game.dead||game.won)return;const show=typeof force==='boolean'?force:!loadoutOpen;loadoutOpen=show;$('loadoutOverlay').classList.toggle('hidden',!show);if(show){if(mapOpen)setMap(false);paused=true;$('gamePauseMenu').classList.add('hidden');$('pause').classList.add('hidden');renderLoadout();}else{paused=false;canvas.focus();}}
$('loadoutContent').addEventListener('click',e=>{const button=e.target.closest('button[data-gear]');if(button)equipGear(button.dataset.gear);const remove=e.target.closest('button[data-unequip-gear]');if(remove)unequipGear(remove.dataset.unequipGear);});$('loadoutContent').addEventListener('change',e=>{if(e.target.matches('select[data-weapon-slot]'))switchModFromBag(e.target);if(e.target.matches('select[data-talent-weapon]')){const id=Number(e.target.dataset.talentWeapon),level=Number(e.target.dataset.talentLevel),choice=e.target.value,allowed=level===6?['precision','mobility']:level===10?['sustain','execution']:[];if(masteryLevel(id)>=level&&allowed.includes(choice)){talents[id]??={};talents[id][level]=choice;saveTalents();renderLoadout();updateHud();}}});$('forgeGearContent').addEventListener('click',e=>{const equip=e.target.closest('button[data-gear]'),remove=e.target.closest('button[data-unequip-gear]');if(equip)equipGear(equip.dataset.gear);if(remove){gearBuild[remove.dataset.unequipGear]=null;saveGearBuild();if(game?.inHub){const p=game.player;p.equipment=savedGearEquipment();p.maxHp=p.baseMaxHp+gearStats().hp;p.hp=Math.min(p.hp,p.maxHp);updateHud();}renderGearWorkbench();}const slot=e.target.closest('button[data-select-gear-slot]');if(slot){activeGearSlot=activeGearSlot===slot.dataset.selectGearSlot?null:slot.dataset.selectGearSlot;renderGearWorkbench();}const close=e.target.closest('button[data-close-gear-slot]');if(close){activeGearSlot=null;renderGearWorkbench();}const locker=e.target.closest('button[data-locker-gear]');if(locker)selectLockerGear(locker.dataset.lockerGear);});$('loadoutBtn').onclick=()=>toggleLoadout();$('pauseLoadoutBtn').onclick=()=>toggleLoadout(true);$('closeLoadout').onclick=()=>toggleLoadout(false);
function openHelp(){if(!game||paused||helpOpen||shopOpen||hubForgeOpen||loadoutOpen||mapOpen||game.dead||game.won)return;helpOpen=true;paused=true;mouse.down=false;$('helpOverlay').classList.remove('hidden');}
function closeHelp(){if(!helpOpen)return;helpOpen=false;$('helpOverlay').classList.add('hidden');paused=false;canvas.focus();}
$('closeHelp').onclick=closeHelp;
function togglePause(){if(helpOpen){closeHelp();return;}if(shopOpen){closeShop();return;}if(loadoutOpen){toggleLoadout(false);return;}if(hubForgeOpen){closeHubForge();return;}if(!game||game.dead||game.won)return;paused=!paused;$('gamePauseMenu').classList.toggle('hidden',!paused);if(!paused)canvas.focus();}
function returnToMainMenu(){if(!game)return;saveSlot();const seed=game.seed;buildGame(seed);setupHub();}
$('resumeGameBtn').onclick=()=>togglePause();$('muteGameBtn').onclick=()=>{muted=!muted;$('muteGameBtn').textContent=muted?'♪ SESİ AÇ':'♪ SESİ KAPAT';};$('mainMenuBtn').onclick=()=>returnToMainMenu();
const drawMap=window.DropForgeMapView.createMapRenderer({getGame:()=>game,mapCanvas,mctx});
function roomRouteLabel(r){const reward={ammo:'MERMİ',mod:'EKLENTİ',xp:'SİLAH XP',health:'SAĞLIK'}[r.reward]||'ÖDÜL';return roomName(r)+(r.bossKey?(r.bossKeyCollected?' · ANAHTAR ALINDI':' · BOSS ANAHTARI'):'')+(r.type==='boss'?' '+r.bossStage+'/4':r.type==='start'?'':' · '+reward)+' · '+BIOMES[r.biome].name+' · LV '+r.level;}
function setMap(on){if(shopOpen||hubForgeOpen||helpOpen||!game||game.dead||game.won)return;mapOpen=on;$('mapOverlay').classList.toggle('hidden',!on);if(on){drawMap();const routes=Object.entries(currentRoom().links).map(([dir,id])=>({dir,room:game.rooms[id]}));const names={left:'SOL',right:'SAĞ',up:'YUKARI',down:'AŞAĞI'};$('mapRoute').textContent=routes.length?'BOSS ANAHTARI '+game.bossKeys+'/3 · KOMŞU ODALAR: '+routes.map(({dir,room})=>names[dir]+' → '+roomRouteLabel(room)).join('  |  '):'Bu odadan başka geçiş bulunmuyor.';}else canvas.focus();}
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright','shift','tab'].includes(k))e.preventDefault();if(k==='m'){if(shopOpen||hubForgeOpen||helpOpen||testLabOpen)return;if(!e.repeat)setMap(!mapOpen);return;}if(k==='escape'){if(!e.repeat){if(testLabOpen)closeTestLab();else if(helpOpen)closeHelp();else if(hubForgeOpen)closeHubForge();else if(shopOpen)closeShop();else if(loadoutOpen)toggleLoadout(false);else if(mapOpen)setMap(false);else togglePause();}return;}if(k==='tab'||k==='i'){if(shopOpen||hubForgeOpen||helpOpen||testLabOpen)return;if(!e.repeat)toggleLoadout();return;}if(k==='e'&&!e.repeat)interact();if(['1','2'].includes(k)&&!e.repeat&&game&&!paused)equipSlot(Number(k)-1);if((k==='3'||k==='h')&&!e.repeat)useKit();if(k==='4'&&!e.repeat)throwGrenade();if(k==='5'&&!e.repeat)useAccessory(0);if(k==='q'&&!e.repeat)dropHeldWeapon();if(k==='r'&&!e.repeat)reloadWeapon();if(k==='v'&&!e.repeat&&game&&!paused&&!mapOpen&&shootTimer<=0)melee();if(!game||paused||mapOpen)return;const p=game.player;if((k===' '||k==='w'||k==='arrowup')&&!e.repeat&&(p.jumps<2||p.wallSide)){if(p.grapple)p.grapple=null;if(p.wallSide){p.vy=-575;p.vx=-p.wallSide*390;p.face=-p.wallSide;p.wallKick=.19;p.moveCharge=1.6;p.wallSide=0;p.jumps=1;p.grounded=false;burst(currentRoom(),p.x+p.w/2,p.y+p.h/2,'#a9e6ff',13,145);sound(470,.1,'triangle');keys.add(k);return;}if(p.jumps===1){p.spin=0;p.spinDuration=.49;burst(currentRoom(),p.x+p.w/2,p.y+p.h,'#9adffd',11,160);sound(590,.1,'triangle');}p.vy=p.jumps===0?-580:-515;p.jumps++;p.grounded=false;p.dash=0;}if(k==='shift'&&!e.repeat&&p.dashCooldown<=0){burst(currentRoom(),p.x+p.w/2,p.y+p.h/2,'#98e8ff',14,185);sound(310,.13,'sawtooth');p.grapple=null;p.dash=.16;p.moveCharge=1.6;p.dashCooldown=.95;p.invuln=Math.max(p.invuln,.19);game.motionTrails.push({x:p.x+p.w/2,y:p.y+p.h/2,face:p.face,life:.32,maxLife:.32,kind:'dash'});shake=Math.max(shake,3);}if(k==='z'&&!e.repeat){grappleToggle();sound(720,.07,'triangle',.014);}keys.add(k);});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();mouse.down=false;if(game&&!paused&&!game.dead&&!game.won)togglePause();});canvas.addEventListener('mousemove',e=>{const r=canvas.getBoundingClientRect();mouse.x=(e.clientX-r.left)*W/r.width;mouse.y=(e.clientY-r.top)*H/r.height;});canvas.addEventListener('mousedown',e=>{if(e.button===0){mouse.down=true;canvas.focus();}else if(e.button===2){e.preventDefault();canvas.focus();useWeaponAbility();}});window.addEventListener('mouseup',()=>mouse.down=false);canvas.addEventListener('contextmenu',e=>e.preventDefault());$('mapBtn').onclick=()=>setMap(!mapOpen);$('closeMap').onclick=()=>setMap(false);$('helpBtn').onclick=openHelp;$('startBtn').onclick=()=>{if(game?.inHub&&hubForgeOpen){applyHubForge();return;}let raw=$('seedInput').value.trim(),seed=raw?Number(raw):Math.floor(Math.random()*2147483647);if(!Number.isSafeInteger(seed)||seed<1)seed=382711;buildGame(seed>>>0);setupHub();};
for(let i=0;i<2;i++)$('slot'+(i+1)).onclick=()=>{if(game&&!paused)equipSlot(i);};$('slot3').onclick=()=>useKit();$('slot4').onclick=()=>throwGrenade();$('slot5').onclick=()=>useAccessory(0);
buildGame(Math.floor(Math.random()*2147483646)+1);setupHub();
function loop(ts){const dt=Math.min((ts-last)/1000||0,.04);last=ts;if(hitStop>0)hitStop-=dt;else update(dt);draw();requestAnimationFrame(loop);}requestAnimationFrame(loop);
window.__dropForgeDebug=()=>game?{x:game.player.x,y:game.player.y,grounded:game.player.grounded,room:game.roomId,layout:currentRoom().layout,biome:currentRoom().biome,terrain:currentRoom().terrain,difficulty:game.difficulty,mastery:{...mastery},weapons:game.player.slots.map(q=>q&&{weapon:q.weapon,mods:q.mods}),stashedMods:[...game.stashedMods],enemyCap:currentRoom().enemyCap,portals:currentRoom().portals.map(q=>({hp:q.hp,regenCap:q.regenCap,shield:q.shield,shieldTriggered:q.shieldTriggered,overdrive:q.overdrive,produced:q.produced,max:q.max}))}:null;
